// Documinder core — deterministic credential classification (Phase 1).
//
// Pure functions with no dependencies, so the same code runs in three places:
//   1. Node unit tests (tests/core.test.mjs)
//   2. The n8n "Classify credentials" Code node (see workflows/)
//   3. Anyone reading the repo who wants to understand the rules
//
// No LLM is involved. Dates are compared as calendar days, never as timestamps.

const MS_PER_DAY = 86400000;

const ENDORSEMENT_TYPES = ['HAZMAT_ENDORSEMENT', 'TANKER_ENDORSEMENT', 'DOUBLES_TRIPLES_ENDORSEMENT'];
const DEFAULT_STAGES = [90, 60, 30, 14, 7, 0];

// ---------- Dates ----------

// Parses a strict YYYY-MM-DD string into a whole-day number (days since 1970-01-01).
// Rejects malformed strings and impossible dates such as 2026-02-30.
function parseCalendarDate(value) {
  if (value === null || value === undefined || String(value).trim() === '') {
    return { ok: false, reason: 'blank' };
  }
  const s = String(value).trim();
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return { ok: false, reason: `malformed date "${s}" (expected YYYY-MM-DD)` };
  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const ms = Date.UTC(y, mo - 1, d);
  const check = new Date(ms);
  if (check.getUTCFullYear() !== y || check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) {
    return { ok: false, reason: `impossible calendar date "${s}"` };
  }
  return { ok: true, day: Math.round(ms / MS_PER_DAY), iso: s };
}

// Today's calendar date (YYYY-MM-DD) in the business timezone.
function todayInTimezone(timeZone, now = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const get = (t) => parts.find((p) => p.type === t).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

// The fixed test date wins when set; otherwise use the real date in the business timezone.
function resolveReferenceDate(settings, now = new Date()) {
  const tz = settings.business_timezone || 'America/Los_Angeles';
  const fixed = settings.test_reference_date;
  if (fixed !== null && fixed !== undefined && String(fixed).trim() !== '') {
    const parsed = parseCalendarDate(fixed);
    if (!parsed.ok) throw new Error(`Settings.test_reference_date is invalid: ${parsed.reason}`);
    return { iso: parsed.iso, day: parsed.day, source: 'test_reference_date', timeZone: tz };
  }
  const iso = todayInTimezone(tz, now);
  return { iso, day: parseCalendarDate(iso).day, source: 'current_date', timeZone: tz };
}

// ---------- Policy ----------

function parseStages(value) {
  if (value === null || value === undefined || String(value).trim() === '') return DEFAULT_STAGES.slice();
  const stages = String(value)
    .split(',')
    .map((s) => Number(s.trim()))
    .filter((n) => Number.isInteger(n) && n >= 0);
  return [...new Set(stages)].sort((a, b) => b - a);
}

// State is defined by the reminder policy table in the build brief.
function stateForDays(days) {
  if (days < 0) return 'overdue';
  if (days === 0) return 'expires_today';
  if (days <= 7) return 'critical';
  if (days <= 30) return 'urgent';
  if (days <= 90) return 'approaching_expiry';
  return 'current';
}

// Only the *current* applicable stage is returned; missed earlier stages are never replayed.
// Example with stages 90,60,30,14,7,0: 45 days left -> D60, 90 -> D90, 91 -> none.
function stageForDays(days, stages) {
  if (days < 0) return 'OVERDUE';
  const due = stages.filter((s) => s >= days);
  if (due.length === 0) return '';
  return `D${Math.min(...due)}`;
}

function actionFor(state, escalationPolicy) {
  const escalates = escalationPolicy !== 'none';
  switch (state) {
    case 'approaching_expiry':
    case 'urgent':
    case 'critical':
      return 'driver_reminder';
    case 'expires_today':
      return escalates ? 'driver_notice_and_staff_escalation' : 'driver_notice';
    case 'overdue':
      return escalates ? 'staff_escalation' : 'none';
    case 'missing':
    case 'invalid_date':
      return 'staff_review';
    default:
      return 'none';
  }
}

// ---------- Documents ----------

function isTrue(v) {
  return v === true || v === 'true' || v === 'TRUE' || v === 1 || v === '1';
}

// Latest verified version of one document type for one driver (archived/pending rows ignored).
function latestVerified(documents, driverId, documentType) {
  return documents
    .filter((d) => d.driver_id === driverId && d.document_type === documentType && d.status === 'verified')
    .sort((a, b) => Number(b.version) - Number(a.version))[0];
}

// ---------- Classification ----------

function classifyAll({ settings, drivers, requirements, documents, now = new Date() }) {
  const ref = resolveReferenceDate(settings, now);
  const rows = [];

  for (const driver of drivers) {
    const active = isTrue(driver.active);
    const reqs = requirements.filter((r) => r.applicable_role === driver.role);

    if (reqs.length === 0) {
      rows.push(baseRow(ref, driver, { document_type: '*' }, {
        state: 'invalid_date',
        action: 'staff_review',
        reason: `no requirements configured for role "${driver.role}"`,
      }));
      continue;
    }

    for (const req of reqs) {
      if (!active) {
        rows.push(baseRow(ref, driver, req, { state: 'inactive_skipped', reason: 'driver is inactive' }));
        continue;
      }
      if (!isTrue(req.required)) {
        rows.push(baseRow(ref, driver, req, { state: 'not_applicable', reason: `not required for role ${driver.role}` }));
        continue;
      }

      const doc = latestVerified(documents, driver.driver_id, req.document_type);
      if (!doc) {
        rows.push(baseRow(ref, driver, req, {
          state: 'missing',
          action: actionFor('missing'),
          reason: 'required document has no verified version on file',
        }));
        continue;
      }

      // Endorsements may share the CDL expiration date. Never invent a date:
      // inherit only when the endorsement record is blank and a verified CDL exists.
      let expirationRaw = doc.expiration_date;
      let expirationSource = 'document';
      if ((expirationRaw === null || expirationRaw === undefined || String(expirationRaw).trim() === '') &&
          ENDORSEMENT_TYPES.includes(req.document_type)) {
        const cdl = latestVerified(documents, driver.driver_id, 'CDL');
        if (cdl) {
          expirationRaw = cdl.expiration_date;
          expirationSource = `inherited_from_cdl:${cdl.document_id}`;
        }
      }

      const exp = parseCalendarDate(expirationRaw);
      const docFields = {
        document_id: doc.document_id,
        document_version: Number(doc.version),
        expiration_date: expirationRaw === null || expirationRaw === undefined ? '' : String(expirationRaw),
        expiration_source: expirationSource,
      };

      if (!exp.ok) {
        rows.push(baseRow(ref, driver, req, {
          ...docFields,
          state: 'invalid_date',
          action: actionFor('invalid_date'),
          reason: exp.reason === 'blank' ? 'expiration date not provided' : exp.reason,
        }));
        continue;
      }

      const issue = parseCalendarDate(doc.issue_date);
      if (issue.ok && issue.day > exp.day) {
        rows.push(baseRow(ref, driver, req, {
          ...docFields,
          state: 'invalid_date',
          action: actionFor('invalid_date'),
          reason: `issue_date ${issue.iso} is after expiration_date ${exp.iso}`,
        }));
        continue;
      }

      const days = exp.day - ref.day;
      const state = stateForDays(days);
      const stage = state === 'current' ? '' : stageForDays(days, parseStages(req.reminder_stages));
      rows.push(baseRow(ref, driver, req, {
        ...docFields,
        days_remaining: days,
        state,
        reminder_stage: stage,
        action: actionFor(state, req.escalation_policy),
        reason: `${days} day(s) remaining as of ${ref.iso} (${ref.timeZone})`,
      }));
    }
  }
  return { reference: ref, rows };
}

function baseRow(ref, driver, req, fields) {
  return {
    reference_date: ref.iso,
    reference_source: ref.source,
    driver_id: driver.driver_id,
    full_name: driver.full_name,
    role: driver.role,
    active: isTrue(driver.active),
    requirement_id: req.requirement_id || '',
    document_type: req.document_type,
    document_id: '',
    document_version: null,
    expiration_date: '',
    expiration_source: '',
    days_remaining: null,
    state: '',
    reminder_stage: '',
    action: 'none',
    reason: '',
    // Phase 2 dedup key: driver_id + document_id + document_version + reminder_stage
    dedup_key: '',
    ...fields,
  };
}

function withDedupKeys(rows) {
  return rows.map((r) => ({
    ...r,
    dedup_key: r.reminder_stage && r.document_id
      ? `${r.driver_id}|${r.document_id}|${r.document_version}|${r.reminder_stage}`
      : '',
  }));
}

// Compares actual rows with expected rows keyed by driver_id + document_type.
function compareWithExpected(rows, expected) {
  const actualByKey = new Map(rows.map((r) => [`${r.driver_id}:${r.document_type}`, r]));
  const results = expected.map((e) => {
    const a = actualByKey.get(`${e.driver_id}:${e.document_type}`);
    const actualState = a ? a.state : '(no row)';
    const actualStage = a ? a.reminder_stage : '';
    const pass = actualState === e.expected_state && (actualStage || '') === (e.expected_stage || '');
    return {
      driver_id: e.driver_id,
      full_name: a ? a.full_name : '',
      document_type: e.document_type,
      primary_fixture: isTrue(e.primary_fixture),
      expected_state: e.expected_state,
      actual_state: actualState,
      expected_stage: e.expected_stage || '',
      actual_stage: actualStage || '',
      days_remaining: a ? a.days_remaining : null,
      pass,
    };
  });
  const expectedKeys = new Set(expected.map((e) => `${e.driver_id}:${e.document_type}`));
  const unexpected = rows.filter((r) => !expectedKeys.has(`${r.driver_id}:${r.document_type}`));
  const failed = results.filter((r) => !r.pass).length + unexpected.length;
  return { results, unexpected, total: results.length, passed: results.length - results.filter((r) => !r.pass).length, failed };
}

function summarize(rows) {
  const counts = {};
  for (const r of rows) counts[r.state] = (counts[r.state] || 0) + 1;
  return counts;
}

// ---------- n8n glue ----------
// Reads the tables loaded upstream and returns one item per driver x requirement.
const settings = $('Load Settings').first().json;
const drivers = $('Load Drivers').all().map((i) => i.json);
const requirements = $('Load Requirements').all().map((i) => i.json);
const documents = $('Load Documents').all().map((i) => i.json);

const { rows } = classifyAll({ settings, drivers, requirements, documents });
return withDedupKeys(rows).map((r) => ({ json: r }));

// Phase 1 exit check: compare every classified row with documinder_test_expectations.
const rows = $input.all().map((i) => i.json);
const expected = $('Load Test Expectations').all().map((i) => i.json);
const byKey = new Map(rows.map((r) => [r.driver_id + ':' + r.document_type, r]));

const results = expected.map((e) => {
  const a = byKey.get(e.driver_id + ':' + e.document_type);
  const actualState = a ? a.state : '(no row)';
  const actualStage = a ? a.reminder_stage || '' : '';
  return {
    driver: a ? a.full_name : e.driver_id,
    document_type: e.document_type,
    primary_fixture: e.primary_fixture === true,
    expected: e.expected_state + (e.expected_stage ? ' / ' + e.expected_stage : ''),
    actual: actualState + (actualStage ? ' / ' + actualStage : ''),
    days_remaining: a ? a.days_remaining : null,
    pass: actualState === e.expected_state && actualStage === (e.expected_stage || ''),
  };
});
const expectedKeys = new Set(expected.map((e) => e.driver_id + ':' + e.document_type));
const unexpectedRows = rows.filter((r) => !expectedKeys.has(r.driver_id + ':' + r.document_type));

const stateCounts = {};
for (const r of rows) stateCounts[r.state] = (stateCounts[r.state] || 0) + 1;
const failures = results.filter((r) => !r.pass);

return [{
  json: {
    phase: 'Phase 1: classification engine',
    reference_date: rows[0] ? rows[0].reference_date : null,
    reference_source: rows[0] ? rows[0].reference_source : null,
    exit_check: failures.length === 0 && unexpectedRows.length === 0 ? 'PASS' : 'FAIL',
    checked: results.length,
    passed: results.length - failures.length,
    failed: failures.length + unexpectedRows.length,
    state_counts: stateCounts,
    primary_fixtures: results.filter((r) => r.primary_fixture),
    failures,
    unexpected_rows: unexpectedRows.map((r) => r.driver_id + ':' + r.document_type),
  },
}];

// Documinder reminders — Phase 2: compose preview reminders and deduplicate them
// against notification history. Deterministic templates, no LLM.
//
// Runs in Node tests (tests/reminders.test.mjs) and in the n8n
// "Plan Reminders (dedup)" Code node (embedded by scripts/build-workflow.mjs).

// Statuses that mean "this reminder already went out, or may have": never create another.
//   pending   = recorded before the send; if a run dies mid-send it stays pending (treated as uncertain)
//   previewed = composed without a provider (Phase 2 dry runs)
// A 'failed' attempt does not block, so it can be retried. 'closed' belongs to a superseded version.
const BLOCKING_STATUSES = ['pending', 'previewed', 'sent', 'uncertain'];

const DOCUMENT_LABELS = {
  CDL: 'Commercial Driver\'s License (CDL)',
  MEDICAL_CERT: 'Medical Examiner\'s Certificate',
  TWIC: 'TWIC card',
  HAZMAT_ENDORSEMENT: 'Hazmat endorsement',
  TANKER_ENDORSEMENT: 'Tanker endorsement',
  DOUBLES_TRIPLES_ENDORSEMENT: 'Doubles/triples endorsement',
  SAFETY_TRAINING: 'Defensive-driving / safety training',
};

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

function formatDate(iso) {
  const [y, m, d] = String(iso).split('-').map(Number);
  return `${MONTHS[m - 1]} ${d}, ${y}`;
}

function whenPhrase(days) {
  if (days > 1) return `in ${days} days`;
  if (days === 1) return 'tomorrow';
  if (days === 0) return 'today';
  return `${-days} day${days === -1 ? '' : 's'} ago`;
}

// Who the reminder is meant for, by stage. Overdue goes to staff only (no repeated driver emails).
function audienceFor(stage) {
  if (stage === 'OVERDUE') return 'staff';
  if (stage === 'D0') return 'driver_and_staff';
  return 'driver';
}

function composeReminder(row, driver, settings) {
  const label = DOCUMENT_LABELS[row.document_type] || row.document_type;
  const audience = audienceFor(row.reminder_stage);
  const when = whenPhrase(row.days_remaining);
  const expires = formatDate(row.expiration_date);
  const inherited = String(row.expiration_source || '').startsWith('inherited_from_cdl')
    ? ' (this endorsement shares your CDL expiration date)'
    : '';

  const recipients = [];
  if (audience !== 'staff') recipients.push(driver.email);
  if (audience !== 'driver') recipients.push(driver.manager_email);

  let subject;
  let lines;
  if (audience === 'staff') {
    subject = `Staff escalation: ${driver.full_name}'s ${label} expired ${when}`;
    lines = [
      `${driver.full_name} (${driver.driver_id}) has an expired ${label}.`,
      `Expiration date: ${expires}${inherited}.`,
      'Please follow up with the driver and record a renewal. Documinder will not keep emailing the driver about this.',
    ];
  } else {
    const urgency = { D90: 'Heads-up', D60: 'Reminder', D30: 'Action needed', D14: 'Action needed', D7: 'Final reminder', D0: 'Expires today' }[row.reminder_stage] || 'Reminder';
    subject = row.reminder_stage === 'D0'
      ? `Expires today: your ${label}`
      : `${urgency}: your ${label} expires ${when}`;
    lines = [
      `Hi ${driver.full_name.split(' ')[0]},`,
      `Your ${label} expires ${when}, on ${expires}${inherited}.`,
      'Please submit your renewed document so the compliance team can verify it.',
    ];
    if (audience === 'driver_and_staff') lines.push(`Your manager (${driver.manager_email}) has been copied.`);
  }

  return { audience, recipients, subject, body: lines.join('\n\n') };
}

// Decides, for every row with a due reminder stage, whether to create a new preview
// notification or skip it because a blocking attempt already exists.
// simulations: optional [{ driver_id, document_type, outcome: 'failure' | 'timeout' }] used to force a
// provider outcome in tests. Ignored unless preview_only is on, so it can never affect live sends.
function planNotifications({ rows, drivers, settings, history, simulations = [], now = new Date(), runId = 'local' }) {
  const previewOnly = settings.preview_only === true || settings.preview_only === 'true';
  if (previewOnly && !String(settings.test_recipient || '').trim()) {
    throw new Error('preview_only is on but Settings.test_recipient is empty; refusing to address any reminder.');
  }

  const blocked = new Set(
    history
      .filter((n) => n && n.dedup_key && BLOCKING_STATUSES.includes(n.status))
      .map((n) => n.dedup_key),
  );
  const driversById = new Map(drivers.map((d) => [d.driver_id, d]));
  const simulationFor = (row) => {
    if (!previewOnly) return '';
    const sim = simulations.find((x) => x && x.driver_id === row.driver_id && x.document_type === row.document_type);
    return sim ? sim.outcome : '';
  };
  const attemptedAt = now.toISOString();
  const plans = [];
  let seq = 0;

  for (const row of rows) {
    if (!row.reminder_stage || !row.dedup_key) continue;
    const driver = driversById.get(row.driver_id);
    const base = {
      dedup_key: row.dedup_key,
      driver_id: row.driver_id,
      full_name: row.full_name,
      document_id: row.document_id,
      document_type: row.document_type,
      document_version: row.document_version,
      reminder_stage: row.reminder_stage,
      days_remaining: row.days_remaining,
    };

    if (blocked.has(row.dedup_key)) {
      plans.push({ ...base, decision: 'skip_duplicate' });
      continue;
    }
    blocked.add(row.dedup_key); // never plan the same key twice in one run

    const msg = composeReminder(row, driver, settings);
    const intended = msg.recipients.join(', ');
    seq += 1;
    plans.push({
      ...base,
      decision: 'create',
      notification: {
        notification_id: `NTF-${runId}-${String(seq).padStart(3, '0')}`,
        driver_id: row.driver_id,
        document_id: row.document_id,
        document_version: row.document_version,
        reminder_stage: row.reminder_stage,
        dedup_key: row.dedup_key,
        audience: msg.audience,
        intended_recipient: intended,
        delivered_to: previewOnly ? settings.test_recipient : intended,
        delivery_mode: previewOnly ? 'preview' : 'live',
        subject: (previewOnly ? `[PREVIEW for ${intended}] ` : '') + msg.subject,
        body: msg.body,
        from_name: settings.reminder_from_name || 'Documinder',
        simulated_outcome: simulationFor(row),
        provider_message_id: '',
        status: 'pending',
        attempted_at: attemptedAt,
        error_detail: '',
      },
    });
  }
  return plans;
}

function summarizePlans(plans) {
  const created = plans.filter((p) => p.decision === 'create');
  return {
    reminders_due: plans.length,
    created: created.length,
    skipped_duplicates: plans.length - created.length,
    created_by_stage: created.reduce((acc, p) => ({ ...acc, [p.reminder_stage]: (acc[p.reminder_stage] || 0) + 1 }), {}),
  };
}

// ---------- n8n glue ----------
// One item per due reminder stage, each with decision = create | skip_duplicate.
const settings = $('Load Settings').first().json;
const drivers = $('Load Drivers').all().map((i) => i.json);
const history = $('Load Notification History').all().map((i) => i.json).filter((r) => r.dedup_key);
const simulations = $('Load Provider Simulations').all().map((i) => i.json).filter((r) => r.driver_id);
const rows = $input.all().map((i) => i.json);

const plans = planNotifications({ rows, drivers, settings, history, simulations, runId: $execution.id });
return plans.map((p) => ({
  json: {
    decision: p.decision,
    full_name: p.full_name,
    document_type: p.document_type,
    days_remaining: p.days_remaining,
    ...(p.notification || { dedup_key: p.dedup_key, driver_id: p.driver_id, reminder_stage: p.reminder_stage }),
  },
}));

// Documinder delivery — Phase 3: interpret provider outcomes and build the staff-review queue.
// Deterministic, no LLM. Runs in Node tests (tests/delivery.test.mjs) and in the n8n
// "Interpret Provider Result" and "Build Staff Review Items" Code nodes.

// Errors that prove the message was NOT accepted: safe to mark failed (and retry later).
const DEFINITE_FAILURE = [
  /\b5\d\d\b/, // permanent SMTP rejection, e.g. 550 mailbox unavailable
  /\b4\d\d\b/, // temporary SMTP rejection, e.g. 421/451: provider refused before accepting
  /EAUTH|Invalid login|authentication/i, // credentials rejected before anything was sent
  /EENVELOPE|No recipients defined|recipient.*rejected/i,
  /ECONNREFUSED|ENOTFOUND/i, // never connected
];

// Errors where the message may or may not have gone out: never auto-retry.
const UNCERTAIN = [/timeout|timed out|ETIMEDOUT|ESOCKET|ECONNRESET|socket hang up|EPIPE|connection closed/i];

// Maps one provider response (SMTP node success output, error output, or a simulation)
// to the status we record. Anything we cannot positively classify is 'uncertain'.
function interpretProviderResult(response) {
  const r = response || {};
  const err = r.error;
  if (err) {
    const text = [err.code, err.responseCode, err.message, err.description, typeof err === 'string' ? err : '']
      .filter(Boolean).join(' ').trim() || 'unknown provider error';
    if (UNCERTAIN.some((re) => re.test(text))) {
      return { status: 'uncertain', provider_message_id: '', error_detail: `uncertain: ${text}` };
    }
    if (DEFINITE_FAILURE.some((re) => re.test(text))) {
      return { status: 'failed', provider_message_id: '', error_detail: `failed: ${text}` };
    }
    return { status: 'uncertain', provider_message_id: '', error_detail: `uncertain (unrecognized error): ${text}` };
  }

  const accepted = Array.isArray(r.accepted) ? r.accepted : [];
  const rejected = Array.isArray(r.rejected) ? r.rejected : [];
  if (r.messageId && accepted.length > 0 && rejected.length === 0) {
    return { status: 'sent', provider_message_id: String(r.messageId), error_detail: '' };
  }
  if (accepted.length === 0 && rejected.length > 0) {
    return { status: 'failed', provider_message_id: String(r.messageId || ''), error_detail: `failed: provider rejected ${rejected.join(', ')}` };
  }
  return {
    status: 'uncertain',
    provider_message_id: String(r.messageId || ''),
    error_detail: `uncertain: unexpected provider response ${JSON.stringify({ messageId: r.messageId, accepted, rejected, response: r.response }).slice(0, 300)}`,
  };
}

// Simulated provider responses, used only while preview_only is on.
function simulatedResponse(outcome) {
  if (outcome === 'failure') {
    return { error: { code: 'EENVELOPE', responseCode: 550, message: '550 5.1.1 Recipient address rejected: mailbox unavailable (simulated)' } };
  }
  if (outcome === 'timeout') {
    return { error: { code: 'ETIMEDOUT', message: 'Connection timeout after 30000ms (simulated)' } };
  }
  return { error: { message: `unknown simulation "${outcome}"` } };
}

const RECOMMENDED_ACTION = {
  delivery_failed: 'Provider rejected the message. Check the address or provider error; the next run retries automatically.',
  delivery_uncertain: 'Delivery unknown. Check the inbox or provider logs before doing anything; Documinder will NOT resend. Then mark the notification sent or failed.',
  delivery_stuck_pending: 'An earlier run recorded this reminder but never recorded a provider result. Treat as uncertain: confirm before resending.',
  missing_document: 'Collect and verify the required document.',
  invalid_date: 'Correct the expiration date in the source record.',
};

// New staff-review items for this run. Each item has a stable review_key, so a problem that
// persists across daily runs is queued once, not every day.
function buildStaffReviewItems({ rows, deliveries, history, existingKeys, runStartedAt, now = new Date() }) {
